frappe.ui.form.on('Insurance Claim', {

    validate(frm) {
        // if (frm.doc.your_field < 0) {
        //     frappe.throw('Limit Exeeded!');
        // }
    },

    refresh(frm) {

        set_status_color(frm);

        setup_child_attachment_preview(frm, 'details_regarding_bills', 'attachment');
        color_child_rows(frm);
        toggle_mandatory(frm);

        frm.set_df_property('accepted_amount', 'hidden', 1);
        toggle_approved_amount_visibility(frm);

        if (frm.doc.docstatus === 1) {
            setup_show_all_toggle(frm);
            frm.page.sidebar.find('.attachment-row .remove-attachment').hide();
            frm.page.sidebar.find('.add-attachment').hide();
            frm.page.sidebar.find('.attachment-row .remove-btn').hide();
            frm.page.sidebar.find('.add-attachment-btn').hide();
            frm.page.sidebar.find('.explore-btn').hide();

            if (frappe.user.has_role('Insurance Manager')) {
                frm.set_df_property('checked_by_manager', 'read_only', 0);
                frm.set_df_property('checked_by_officer', 'read_only', 0);
            } else {
                frm.set_df_property('checked_by_manager', 'read_only', 1);
                frm.set_df_property('checked_by_officer', 'read_only', 1);
            }

            if (frappe.user.has_role('Insurance User')) {
                frm.set_df_property('checked_by_officer', 'read_only', 0);
            } else {
                frm.set_df_property('checked_by_officer', 'read_only', 1);
            }

            const allowed_roles = ['Insurance Manager', 'Insurance User'];
            const has_role = frappe.user.has_role(allowed_roles);
            frm.fields_dict['details_regarding_bills'].grid.toggle_enable('assessment', has_role);
            frm.fields_dict['details_regarding_bills'].grid.toggle_enable('remark', has_role);
            frm.refresh_field('details_regarding_bills');
            frm.set_df_property('accepted_amount', 'hidden', 0);
            toggle_approved_amount_visibility(frm);
        }

        apply_section_visibility(frm);
        frm.toggle_display('claim_status', true);
        frm.remove_custom_button('Download');

        if (frm.doc.docstatus === 1) {
            frm.set_df_property('claim_status', 'hidden', 0);
            frm.add_custom_button(__('Download'), function () {
                download_claim_pdf(frm);
            }).addClass('btn-primary');

            if (frm.doc.group_no) {
                frm.set_df_property('checked_by_officer', 'read_only', 1);
                frm.set_df_property('checked_by_manager', 'read_only', 1);
                frm.fields_dict['details_regarding_bills'].grid.toggle_enable('assessment', false);
                frm.fields_dict['details_regarding_bills'].grid.toggle_enable('remark', false);
                frm.refresh_field('details_regarding_bills');
                frm.page.btn_secondary.hide();
                frm.page.wrapper.find('.print-icon-wrap, [data-original-title="Print"], .print-icon-button').hide();
                frm.page.wrapper.find('.menu-btn-group').hide();
                frm.remove_custom_button('Download');
            }
        } else if (frm.doc.docstatus === 2) {
            frm.set_df_property('claim_status', 'hidden', 0);
            reset_fields_on_cancel(frm);
        } else {
            frm.set_df_property('claim_status', 'hidden', 1);
            frm.set_value('claim_status', 'Draft');
            frm.set_value('checked_by_manager', '');
            frm.set_value('checked_by_officer', '');
            frm.toggle_display('claim_status', false);
            if (frm.doc.group_no || frm.doc.group_month) {
                frm.set_df_property('acceptance_of_claim_section', 'hidden', 1);
                frm.set_value('group_no', '');
                frm.refresh_field('group_no');
                frm.set_value('group_month', '');
                frm.refresh_field('group_month');
            }
        }

        if (frm.doc.docstatus === 0 && !frm.is_new() && frm.doc.claim_type === "Surgical and hospital expenses claim") {
            frm.add_custom_button(__('Download'), function () {
                download_claim_pdf(frm);
            }).addClass('btn-primary');
        }

        fetch_purpouses(frm);

        // ------------------------------------------------------------
        // Membership No. (employee) dropdown
        // Insurance Member role only  -> sees ONLY their own number
        // Manager / User / System Mgr -> see all Active members
        // The member is found through the logged-in user's Employee record
        // by looking up Employee.user_id -> Insurance Member (client side only).
        // ------------------------------------------------------------
        load_my_member(frm);

        frm.set_query('employee', function () {
            const filters = { member_status: 'Active' };
            if (is_member_only()) {
                // until the lookup finishes (or if none found) show nothing
                filters.name = frm.__my_member || '__none__';
            }
            return { filters: filters };
        });

        if (is_member_only()) {
            // lock the field once the claim is saved
            frm.set_df_property('employee', 'read_only', frm.is_new() ? 0 : 1);
        }

        frm.set_query('category', function () {
            return { filters: { form_type: 'Surgical and hospital expenses claim' } };
        });

        // Balance table is shown manually via a "View Balance" button next
        // to the Membership Number (employee) field, not automatically.
        // One-way reveal: once opened, it stays open and the button disappears.
        setup_balance_view_button(frm);
        apply_balance_section_visibility(frm);

        if (frm.doc.employee) {
            fetch_and_set_options(frm);
            check_emptype(frm);
        }

        if (frm.is_new()) {
            calculate_total(frm);
            calculate_balance(frm);
            frm.trigger('claim_type');
        }

        frm.toggle_display('amend_section', true);

        let grid = frm.fields_dict["details_regarding_bills"].grid;

        if (grid._add_row_patched) return;
        grid._add_row_patched = true;

        let original_add_new_row = grid.add_new_row.bind(grid);

        grid.add_new_row = function (...args) {
            let rows = frm.doc.details_regarding_bills || [];
            let last_row = rows[rows.length - 1];

            let mandatory_fields = frappe.meta.get_docfields("Claim Bills", frm.doc.name).filter(df => df.reqd).map(df => df.fieldname);

            let is_valid = !last_row || mandatory_fields.every(fn => last_row[fn]);

            if (is_valid) {
                original_add_new_row(...args);
            } else {
                frappe.msgprint(__("Fill in the mandatory fields on the previous row before adding a new one."));
            }
        };
    },

    claim_type(frm) {
        toggle_mandatory(frm);
        apply_section_visibility(frm);
        fetch_purpouses(frm);
        if (frm.doc.docstatus !== 0) return;
        if (frm.is_new()) {
            clear_bottom_form(frm);
            let subtotals = {};
            view_balance_chart(frm, subtotals);
            calculate_balance(frm);
            calculate_total(frm);
        }
    },

    employee(frm) {
        if (frm.doc.docstatus !== 0) return;

        if (frm.doc.employee) {
            fetch_and_set_options(frm);
        } else {
            frm.fields_dict['details_regarding_bills'].grid.update_docfield_property(
                'patiants_name', 'options', ''
            );
            frm.fields_dict['details_regarding_bills'].grid.refresh();
        }

        check_emptype(frm);

        if (frm.is_new()) {
            let subtotals = {};
            view_balance_chart(frm, subtotals);
            clear_bottom_form(frm);
        }
    },

    amount(frm) {
        calculate_balance(frm);
    },

    agrahara_settled_amount(frm) {
        calculate_balance(frm);
    },

    checked_by_manager(frm) {
        let assessment = frm.doc.checked_by_manager;
        let status = assessment != "Accepted" ? "Declined by Manager" : "Accepted by Manager";

        frm.doc.claim_status = status;
        frm.refresh_field('claim_status');
        toggle_approved_amount_visibility(frm);
    },

    checked_by_officer(frm) {
        let assessment = frm.doc.checked_by_officer;
        let status = assessment != "Accepted" ? "Declined by Officer" : "Accepted by Officer";

        frm.doc.claim_status = status;
        frm.doc.checked_by_manager = "";
        frm.refresh_field('claim_status');
        frm.refresh_field('checked_by_manager');
        toggle_approved_amount_visibility(frm);
    },
});

frappe.ui.form.on('Claim Bills', {

    form_render: function (frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        frm.fields_dict['details_regarding_bills'].grid.grid_rows_by_docname[cdn].refresh_field('assessment');
        frm.fields_dict['details_regarding_bills'].grid.grid_rows_by_docname[cdn].refresh_field('remark');

        // FIX: frm.open_grid_row() was being called unconditionally here,
        // including on submitted/cancelled docs. Re-opening/re-rendering the
        // grid row's controls on a locked doc was flipping the form to
        // "Not Saved" even though nothing meaningful changed. Only do the
        // open + date-range setup on an actual draft.
        if (frm.doc.docstatus !== 0) {
            disable_negative_purpose_options(frm);
            return;
        }
        
        add_merge_button(frm, cdt, cdn);

        const grid_row = frm.open_grid_row();
        if (!grid_row) return;

        // small delay ensures grid_form.fields_dict is fully populated
        setTimeout(() => {
            set_child_date_range(frm, grid_row, 'issue_date');
            // grey out (but keep visible) purpose options whose category
            // is currently over its limit, in the row that was just opened.
            disable_negative_purpose_options(frm);
        }, 100);
    },

