                doctype: 'Covers and Benefits',
                filters: [['Purpose', 'purpose', '=', row.purpose]],
                fields: ['c_name'],
                limit: 1
            },
            callback(r) {
                if (!r.message.length) return;
                frappe.model.set_value(cdt, cdn, 'category', r.message[0].c_name);
                calculate_total(frm);

                // Purpose is never hidden — but we still warn (non-blocking)
                // if this category happens to already be over its limit,
                // and refresh the row highlight + disabled options.
                warn_if_category_negative(frm, r.message[0].c_name);
                color_child_rows(frm);
                disable_negative_purpose_options(frm);
