// ================== MERGE FILES TO PDF (browser only) ==================
const MERGE_CONFIG = {
    table_fieldname: 'details_regarding_bills',  // child table fieldname on Insurance Claim
    attach_fieldname: 'attachment',              // Attach field inside the child table
    filename: 'merged.pdf',
};

function load_pdf_lib() {
    return new Promise((resolve, reject) => {
        if (window.PDFLib) return resolve();
        const s = document.createElement('script');
        // Offline server? Host this file in your app and change the path.
        s.src = '/assets/staff_medclaim/js/pdf-lib.min.js';
        s.onload = resolve;
        s.onerror = () => reject(new Error('Could not load pdf-lib'));
        document.head.appendChild(s);
    });
}

async function merge_in_browser(files) {
    const { PDFDocument } = window.PDFLib;
    const out = await PDFDocument.create();
    const A4 = [595.28, 841.89], MARGIN = 20;

    for (const f of files) {
        const bytes = await f.arrayBuffer();
        const name = f.name.toLowerCase();

        if (name.endsWith('.pdf')) {
            const src = await PDFDocument.load(bytes, { ignoreEncryption: true });
            const pages = await out.copyPages(src, src.getPageIndices());
            pages.forEach(p => out.addPage(p));
        } else {
            let img;
            if (name.endsWith('.jpg') || name.endsWith('.jpeg')) img = await out.embedJpg(bytes);
            else if (name.endsWith('.png')) img = await out.embedPng(bytes);
            else throw new Error('Unsupported file: ' + f.name);

            const maxW = A4[0] - MARGIN * 2, maxH = A4[1] - MARGIN * 2;
            const scale = Math.min(maxW / img.width, maxH / img.height, 1);
            const w = img.width * scale, h = img.height * scale;
            const page = out.addPage(A4);
            page.drawImage(img, { x: (A4[0] - w) / 2, y: (A4[1] - h) / 2, width: w, height: h });
        }
    }
    return await out.save();
}

// Only called when the user clicks "Upload Final"
async function upload_merged_pdf(blob, frm, filename) {
    const fd = new FormData();
    fd.append('file', blob, filename);
    fd.append('is_private', 1);

    if (!frm.is_new()) {
        fd.append('doctype', frm.doctype);
        fd.append('docname', frm.doc.name);
    }

    const res = await fetch('/api/method/upload_file', {
        method: 'POST',
        headers: { 'X-Frappe-CSRF-Token': frappe.csrf_token },
        body: fd,
    });
    if (!res.ok) throw new Error(await res.text());
    return (await res.json()).message;
}

// Replaces the native Attach button's click so it opens our popup instead
function add_merge_button(frm, cdt, cdn) {
    setTimeout(() => {
        const grid = frm.fields_dict[MERGE_CONFIG.table_fieldname].grid;
        const grid_row = grid.grid_rows_by_docname[cdn];
        const grid_form = grid_row && grid_row.grid_form;
        const field = grid_form && grid_form.fields_dict[MERGE_CONFIG.attach_fieldname];
        if (!field || field.__merge_patched) return;

        field.__merge_patched = true;
        field.on_attach_click = function () {
            open_merge_dialog(frm, cdt, cdn);
        };
    }, 150);
}

function open_merge_dialog(frm, cdt, cdn) {
    let files = [];
    let final_blob = null;      // merged PDF, or the original file when only one is chosen
    let final_name = MERGE_CONFIG.filename;
    let preview_url = null;

    const d = new frappe.ui.Dialog({
        title: __('Upload / Merge Files'),
        size: 'extra-large',
        fields: [{ fieldtype: 'HTML', fieldname: 'body' }],
        primary_action_label: __('Upload Final'),
        async primary_action() {
            if (!final_blob) return;
            d.get_primary_btn().prop('disabled', true);
            try {
                const file = await upload_merged_pdf(final_blob, frm, final_name);
                await frappe.model.set_value(cdt, cdn, MERGE_CONFIG.attach_fieldname, file.file_url);
                frm.refresh_field(MERGE_CONFIG.table_fieldname);
                frappe.show_alert({ message: __('File attached'), indicator: 'green' });
                d.hide();
            } catch (e) {
                frappe.msgprint({ title: __('Upload failed'), message: String(e), indicator: 'red' });
                d.get_primary_btn().prop('disabled', false);
            }
        },
    });
    d.get_primary_btn().prop('disabled', true);

    const $w = d.fields_dict.body.$wrapper;
    $w.html(`
        <input type="file" class="mf-input" multiple accept=".pdf,.jpg,.jpeg,.png" style="display:none">
        <div style="margin-bottom:10px">
            <button type="button" class="btn btn-default btn-sm mf-pick">${__('Select files')}</button>
            <button type="button" class="btn btn-primary btn-sm mf-merge" disabled>${__('Preview')}</button>
        </div>
        <div class="mf-list" style="margin-bottom:10px"></div>
        <iframe class="mf-preview" style="width:100%;height:65vh;border:1px solid #ddd;display:none"></iframe>
    `);

    const $input = $w.find('.mf-input'),
          $list = $w.find('.mf-list'),
          $merge = $w.find('.mf-merge'),
          $frame = $w.find('.mf-preview');

    function merge_label() {
        return files.length > 1 ? __('Merge & Preview') : __('Preview');
    }

    function reset_result() {
        final_blob = null;
        if (preview_url) URL.revokeObjectURL(preview_url);
        preview_url = null;
        $frame.hide().attr('src', '');
        d.get_primary_btn().prop('disabled', true);
    }

    function render_list() {
        $list.empty();
        files.forEach((f, i) => {
            const $row = $(`
                <div class="flex" style="gap:6px;align-items:center;margin-bottom:4px">
                    <span style="flex:1">${i + 1}. ${frappe.utils.escape_html(f.name)}</span>
                    <button type="button" class="btn btn-xs btn-default up">↑</button>
                    <button type="button" class="btn btn-xs btn-default down">↓</button>
                    <button type="button" class="btn btn-xs btn-danger rm">✕</button>
                </div>`);
            $row.find('.up').on('click', () => move(i, -1));
            $row.find('.down').on('click', () => move(i, 1));
            $row.find('.rm').on('click', () => { files.splice(i, 1); changed(); });
            $list.append($row);
        });
        $merge.prop('disabled', files.length < 1).text(merge_label());
    }

    function move(i, dir) {
        const j = i + dir;
        if (j < 0 || j >= files.length) return;
        [files[i], files[j]] = [files[j], files[i]];
        changed();
    }
    function changed() { reset_result(); render_list(); }

    $w.find('.mf-pick').on('click', () => $input.trigger('click'));
    $input.on('change', e => {
        files = files.concat(Array.from(e.target.files));
        $input.val('');
        changed();
    });

    $merge.on('click', async () => {
        $merge.prop('disabled', true).text(__('Processing...'));
        try {
            if (files.length === 1) {
                // single file: upload as-is, no merge
                final_blob = files[0];
                final_name = files[0].name;
            } else {
                await load_pdf_lib();
                const bytes = await merge_in_browser(files);
                final_blob = new Blob([bytes], { type: 'application/pdf' });
                final_name = MERGE_CONFIG.filename;
            }
            preview_url = URL.createObjectURL(final_blob);
            $frame.attr('src', preview_url).show();
            d.get_primary_btn().prop('disabled', false);
        } catch (e) {
            frappe.msgprint({ title: __('Failed'), message: String(e), indicator: 'red' });
        }
        $merge.prop('disabled', files.length < 1).text(merge_label());
    });

    d.onhide = () => { if (preview_url) URL.revokeObjectURL(preview_url); };
    d.show();
}

