const PARENT_DT   = 'Employee Details';
const CHILD_DT    = 'Dependent';
const CHILD_TABLE = 'dependents';

// Child fields that are never compared
const IGNORE_FIELDS = new Set([
    'name', 'idx', 'owner', 'creation', 'modified', 'modified_by',
    'docstatus', 'parent', 'parentfield', 'parenttype',
    '__islocal', '__unsaved', 'doctype', 'row_status', 'source_row'
]);

// Main fields that are never compared (add calculated fields here)
const PARENT_IGNORE = new Set([
    'name', 'owner', 'creation', 'modified', 'modified_by', 'docstatus',
    'amended_from', 'naming_series', 'workflow_state', 'idx',
    'verify', 'approve'
]);

// Changed on the form, but never listed in the summary message
const SUMMARY_IGNORE = new Set(['emp_no']);   // "Emp No"

const LAYOUT_TYPES = new Set([
    'Section Break', 'Column Break', 'Tab Break', 'HTML', 'Button',
    'Heading', 'Image', 'Fold', 'Table', 'Table MultiSelect'
]);
const NUMERIC_TYPES = new Set(['Check', 'Int', 'Float', 'Currency', 'Percent']);
const ATTACH_TYPES  = new Set(['Attach', 'Attach Image']);

const STATUS = {
    NEW:         'New',           // used for colouring only, never shown as wording
    CHANGED:     'Changed',
    NOT_CHANGED: 'Not Changed'
};

const STYLE = {
    'New':         { bg: '#e8f5e9', badge: '#388e3c' },
    'Changed':     { bg: '#fff8e1', badge: '#f57f17' },
    'Not Changed': { bg: '',        badge: ''         },
};

const CHANGED_CELL_BG = '#ffe082';   // the individual changed field in the table view

// ─── Guards ───────────────────────────────────────────────────────
function is_amended(frm) {
    return !!frm.doc.amended_from;
}

// Compare only while the amended document is still a draft
function should_compare(frm) {
    return is_amended(frm) && frm.doc.docstatus === 0;
}

function is_compared_parent_field(df) {
    return !!df && !!df.fieldname
        && !LAYOUT_TYPES.has(df.fieldtype)
        && !PARENT_IGNORE.has(df.fieldname);
}

function is_compared_child_field(df) {
    return !!df && !!df.fieldname
        && !LAYOUT_TYPES.has(df.fieldtype)
        && !IGNORE_FIELDS.has(df.fieldname);
}

// True for a normal employee: none of the HR / admin roles.
// Such a user may only create / select their OWN Employee record.
function is_self_only() {
    return !frappe.user.has_role(['HR User', 'HR Manager', 'System Manager']);
}

// ─── Parent form ──────────────────────────────────────────────────
frappe.ui.form.on(PARENT_DT, {

    setup(frm) {
        register_field_handlers();

        // Employee dropdown: HR / admin see everyone,
        // a normal employee sees only the Employee record linked to their login
        // (Employee.user_id = logged-in user).
        frm.set_query('employee', function () {
            if (is_self_only()) {
                return { filters: { user_id: frappe.session.user } };
            }
            return {};
        });
    },

    refresh(frm) {

        const is_hr_any     = frappe.user.has_role(['HR User', 'HR Manager']);
        const is_hr_manager = frappe.user.has_role('HR Manager');

        if ((frm.doc.verify == 1 && !is_hr_any) ||
            (frm.doc.approve == 1 && !is_hr_manager)) {

            frm.set_read_only(true);

            frappe.get_meta(PARENT_DT).fields.forEach(df => {
                if (df.fieldname) frm.set_df_property(df.fieldname, 'read_only', 1);
            });

            const grid = frm.fields_dict[CHILD_TABLE] && frm.fields_dict[CHILD_TABLE].grid;
            if (grid) {
                grid.df.read_only = 1;
                grid.refresh();
            }
        }

        // ── existing form behaviour ──
        if (frm.doc.marital_status === 'Single') {
            frm.set_df_property('dependents_details_section', 'hidden', 1);
        }

        if (frm.doc.marriage_certificate) {
            frm.set_df_property('marriage_certificate', 'read_only', 0);
        }

        frm.set_df_property('verify', 'read_only', 1);
        frm.set_df_property('approve', 'read_only', 1);

        if (frappe.user.has_role('HR Manager') && frm.doc.verify == 1) {
            frm.set_df_property('approve', 'read_only', 0);
        }

        if (frappe.user.has_role('HR User') && frm.doc.approve != 1) {
            frm.set_df_property('verify', 'read_only', 0);
        }

        if (frappe.user.has_role('HR Manager') && !frappe.user.has_role('HR User') && frm.doc.verify == 1) {
            frappe.get_meta(PARENT_DT).fields.forEach(df => {
                if (!df.fieldname || df.fieldname === 'approve') return;
                if (LAYOUT_TYPES.has(df.fieldtype)) return;
                frm.set_df_property(df.fieldname, 'read_only', 1);
            });

            const hm_grid = frm.fields_dict[CHILD_TABLE] && frm.fields_dict[CHILD_TABLE].grid;
            if (hm_grid) {
                hm_grid.df.read_only = 1;
                hm_grid.refresh();
            }

            frm.set_df_property('approve', 'read_only', frm.doc.verify == 1 ? 0 : 1);
        }

        const allowed_roles = ['HR Manager', 'HR User'];
        const has_role = frappe.user.has_role(allowed_roles);
        frm.toggle_display(
            'verify_section',
            !!(frm.doc.verify == 1 || frm.doc.approve == 1 || has_role)
        );

        if (frm.doc.docstatus === 1) {
            setup_show_all_toggle(frm);
            frm.page.sidebar.find('.attachment-row .remove-attachment').hide();
            frm.page.sidebar.find('.add-attachment').hide();
            frm.page.sidebar.find('.attachment-row .remove-btn').hide();
            frm.page.sidebar.find('.add-attachment-btn').hide();
            frm.page.sidebar.find('.explore-btn').hide();
        }

        if (frm.fields_dict[CHILD_TABLE]) {
            frm.fields_dict[CHILD_TABLE].grid.add_new_row = function () {
                let row = frappe.model.add_child(frm.doc, CHILD_DT, CHILD_TABLE);
                const all_rows = frm.doc[CHILD_TABLE] || [];
                if (all_rows.length > 1) {
                    frappe.model.set_value(row.doctype, row.name, 'relationship', 'Daughter');
                }
                frm.refresh_field(CHILD_TABLE);
            };
        }

        // ── amend comparison (amended documents in DRAFT only) ──
        // Submitted and cancelled documents behave like a normal DocType.
        if (!should_compare(frm)) {
            clear_comparison_ui(frm);
            return;
        }
        run_comparison(frm);
    },

    // A normal employee may only use their OWN Employee record.
    // Anything else typed/pasted into the field is cleared.
    employee(frm) {
        if (!frm.doc.employee || !is_self_only()) return;

        frappe.db.get_value('Employee', frm.doc.employee, 'user_id').then(r => {
            const emp_user = r.message && r.message.user_id;
            if (emp_user !== frappe.session.user) {
                frm.set_value('employee', '');
                frappe.msgprint({
                    title: __('Not allowed'),
                    message: __('You can only create this for your own Employee record.'),
                    indicator: 'red'
                });
            }
        });
    },

    // Clear row_status on all rows after submit
    before_submit(frm) {
        const promises = (frm.doc[CHILD_TABLE] || []).map(row =>
            frappe.model.set_value(row.doctype, row.name, 'row_status', '')
        );
        return Promise.all(promises);
    },

    // Row names change on the first save, so remember the links by row position
    before_save(frm) {
        if (!should_compare(frm) || !frm._src_rows) return;
        frm._link_snapshot = {};
        (frm.doc[CHILD_TABLE] || []).forEach(r => {
            if (r.source_row && frm._src_rows[r.source_row]) {
                frm._link_snapshot[r.idx] = r.source_row;
            }
        });
    },

    // Re-apply after the grid has been re-rendered with the saved data
    after_save(frm) {
        if (!should_compare(frm)) return;
        setTimeout(() => run_comparison(frm), 500);
    },

    dependents_add(frm, cdt, cdn) {
        if (!should_compare(frm)) return;
        // A brand new row has no original row to link to
        frappe.model.set_value(cdt, cdn, 'source_row', '');
        frappe.model.set_value(cdt, cdn, 'row_status', STATUS.NOT_CHANGED).then(() => {
            show_summary(frm);
            setTimeout(() => colour_row(frm, cdn), 300);
        });
    },

    dependents_remove(frm) {
        if (!should_compare(frm)) return;
        show_summary(frm);
        setTimeout(() => highlight_all_rows(frm), 300);
    },

    marital_status(frm) {
        // Changing marital status invalidates the dependents list
        if ((frm.doc[CHILD_TABLE] || []).length) {
            frm.clear_table(CHILD_TABLE);
            frm.refresh_field(CHILD_TABLE);
        }

        if (frm.doc.marital_status === 'Married') {
            frm.set_df_property('marriage_certificate', 'reqd', 1);
            frm.set_df_property('dependents', 'reqd', 1);
            frm.set_df_property('marriage_certificate', 'read_only', 0);
        } else {
            frm.set_df_property('marriage_certificate', 'reqd', 0);
            frm.set_df_property('dependents', 'reqd', 0);
            frm.set_df_property('marriage_certificate', 'read_only', 1);
        }
        frm.set_df_property(
            'dependents_details_section', 'hidden',
            frm.doc.marital_status === 'Single' ? 1 : 0
        );
    }
});

// ─── Child table events ───────────────────────────────────────────
frappe.ui.form.on(CHILD_DT, {

    form_render(frm, cdt, cdn) {
        if (!should_compare(frm)) return;
        colour_row(frm, cdn);
    },

});

// ─── Generic change handlers (every compared field) ───────────────
function register_field_handlers() {
    if (window.__amend_cmp_registered_employee_details) return;
    window.__amend_cmp_registered_employee_details = true;

    try {
        // Main fields
        const parent_handlers = {};
        frappe.get_meta(PARENT_DT).fields.forEach(df => {
            if (!is_compared_parent_field(df)) return;
            parent_handlers[df.fieldname] = function (frm) {
                on_parent_field_change(frm);
            };
        });
        frappe.ui.form.on(PARENT_DT, parent_handlers);

        // Child row fields
        const child_handlers = {};
        frappe.get_meta(CHILD_DT).fields.forEach(df => {
            if (!is_compared_child_field(df)) return;
            child_handlers[df.fieldname] = function (frm, cdt, cdn) {
                on_child_field_change(frm, cdt, cdn);
            };
        });
        frappe.ui.form.on(CHILD_DT, child_handlers);
    } catch (e) {
        console.warn('Amend comparison: could not register field handlers', e);
    }
}

function on_parent_field_change(frm) {
    if (!should_compare(frm)) return;

    const go = () => fetch_file_meta(collect_attach_urls(frm)).then(() => {
        update_parent_badges(frm);
        show_summary(frm);
    });

    if (!frm._src_doc) load_source(frm).then(go);
    else go();
}

function on_child_field_change(frm, cdt, cdn) {
    if (!should_compare(frm)) return;

    const go = () => fetch_file_meta(collect_attach_urls(frm)).then(() => {
        update_row_status(frm, frappe.get_doc(cdt, cdn));
        colour_row(frm, cdn);
        show_summary(frm);
    });

    if (!frm._src_rows) load_source(frm).then(go);
    else go();
}

// ─── Cleanup: remove every comparison element and cached data ─────
// Runs for anything that is not an amended draft (new docs, normal docs,
// submitted docs, cancelled docs), including right after a draft is submitted.
function clear_comparison_ui(frm) {
    if (frm.$wrapper) {
        frm.$wrapper.find('.changed-badge, .amend-summary, .row-status-badge, .amend-title-badge').remove();
    }

    const grid = frm.fields_dict[CHILD_TABLE] && frm.fields_dict[CHILD_TABLE].grid;
    if (grid) {
        (grid.grid_rows || []).forEach(gr => reset_row_style(gr));
    }

    if (frm._grid_observer) {
        frm._grid_observer.disconnect();
        frm._grid_observer = null;
    }

    frm._src_doc = frm._src_rows = frm._src_list = frm._src_for = null;
    frm._link_snapshot = null;
    frm._warned_src = false;
}

// ─── Main comparison flow ─────────────────────────────────────────
function run_comparison(frm) {
    return load_source(frm)
        .then(() => {
            ensure_links(frm);
            // warn_if_source_field_missing(frm);
            return fetch_file_meta(collect_attach_urls(frm));
        })
        .then(() => {
            observe_grid(frm);
            refresh_all_statuses(frm);
            update_parent_badges(frm);
            show_summary(frm);
            setTimeout(() => {
                highlight_all_rows(frm);
                update_parent_badges(frm);
            }, 300);
        });
}

// ─── Source (cancelled doc) loading ───────────────────────────────
function load_source(frm) {
    if (frm._src_for === frm.doc.amended_from && frm._src_doc) {
        return Promise.resolve();
    }

    return frappe.call({
        method: 'frappe.client.get',
        args: { doctype: frm.doctype, name: frm.doc.amended_from }
    }).then(r => {
        const src = r.message || {};
        const src_rows = (src[CHILD_TABLE] || []).slice()
            .sort((a, b) => a.idx - b.idx);

        frm._src_for  = frm.doc.amended_from;
        frm._src_doc  = src;
        frm._src_list = src_rows;
        frm._src_rows = {};
        src_rows.forEach(row => { frm._src_rows[row.name] = row; });

        ensure_links(frm);
    });
}

// Every row of the amended draft is matched to its row in the cancelled doc
// through the hidden source_row field. On the first save Frappe gives every
// row a new name, so this is checked again on EVERY refresh and repaired if
// the links were lost.
function ensure_links(frm) {
    if (!frm._src_rows) return;
    const rows = frm.doc[CHILD_TABLE] || [];
    if (!rows.length) return;

    const count_valid = () =>
        rows.filter(r => r.source_row && frm._src_rows[r.source_row]).length;

    if (count_valid() > 0) return;

    // 1) Restore the links remembered just before saving (matched by row position)
    if (frm._link_snapshot) {
        rows.forEach(r => { r.source_row = frm._link_snapshot[r.idx] || ''; });
        if (count_valid() > 0) return;
    }

    // 2) First load of the amended draft: rows are still an exact copy of the
    //    cancelled doc, so link by position. Stale values copied from an earlier
    //    amendment are ignored because they don't match any row of the source.
    const src_rows = frm._src_list || [];
    rows.forEach((row, i) => {
        const src_row = src_rows[i];
        row.source_row = src_row ? src_row.name : '';
    });
}

function warn_if_source_field_missing(frm) {
    if (frm._warned_src || frappe.meta.has_field(CHILD_DT, 'source_row')) return;
    frm._warned_src = true;
    frappe.show_alert({
        message: __('Add the hidden field "source_row" (Data) to {0}, otherwise the comparison is lost when the document is saved.', [CHILD_DT]),
        indicator: 'red'
    }, 15);
}

// ─── Attachment helpers (content hash + file name comparison) ─────
const file_cache = {};   // file_url -> { content_hash, file_name }

function fetch_file_meta(urls) {
    const missing = [...new Set((urls || []).filter(u => u && !(u in file_cache)))];
    if (!missing.length) return Promise.resolve();

    return frappe.db.get_list('File', {
        filters: { file_url: ['in', missing] },
        fields: ['file_url', 'content_hash', 'file_name'],
        limit: 1000
    }).then(rows => {
        missing.forEach(u => { file_cache[u] = { content_hash: '', file_name: url_file_name(u) }; });
        (rows || []).forEach(r => {
            file_cache[r.file_url] = {
                content_hash: r.content_hash || '',
                file_name: r.file_name || url_file_name(r.file_url)
            };
        });
    }).catch(() => {
        // No permission or lookup failed: fall back to the name derived from the URL
        missing.forEach(u => { file_cache[u] = { content_hash: '', file_name: url_file_name(u) }; });
    });
}

// Fallback name derived from the URL when File metadata is not available
function url_file_name(url) {
    if (!url) return '';
    try { return decodeURIComponent(url.split('?')[0].split('/').pop()); }
    catch { return url.split('?')[0].split('/').pop(); }
}

// Same file if the URL is identical, or BOTH the file name AND the
// content hash match (same file re-uploaded = unchanged).
function attach_same(a, b) {
    if ((a || '') === (b || '')) return true;
    if (!a || !b) return false;
    const ma = file_cache[a] || { content_hash: '', file_name: url_file_name(a) };
    const mb = file_cache[b] || { content_hash: '', file_name: url_file_name(b) };
    if (ma.file_name !== mb.file_name) return false;
    return !!(ma.content_hash && mb.content_hash && ma.content_hash === mb.content_hash);
}

function collect_attach_urls(frm) {
    const urls = [];

    frappe.get_meta(PARENT_DT).fields.forEach(df => {
        if (!ATTACH_TYPES.has(df.fieldtype)) return;
        urls.push(frm.doc[df.fieldname], (frm._src_doc || {})[df.fieldname]);
    });

    const child_attach = frappe.get_meta(CHILD_DT).fields
        .filter(df => ATTACH_TYPES.has(df.fieldtype));
    const rows = [...(frm.doc[CHILD_TABLE] || []), ...(frm._src_list || [])];
    rows.forEach(r => child_attach.forEach(df => urls.push(r[df.fieldname])));

    return urls.filter(Boolean);
}

// ─── Value comparison ─────────────────────────────────────────────
function norm_value(df, v) {
    if (NUMERIC_TYPES.has(df.fieldtype)) return String(flt(v));
    return String(v ?? '').trim();
}

function values_differ(df, a, b) {
    if (ATTACH_TYPES.has(df.fieldtype)) return !attach_same(a, b);
    return norm_value(df, a) !== norm_value(df, b);
}

// ─── Main (parent) field comparison ───────────────────────────────
function get_changed_parent_fields(frm) {
    if (!frm._src_doc) return [];
    return frappe.get_meta(PARENT_DT).fields.filter(df =>
        is_compared_parent_field(df) &&
        values_differ(df, frm._src_doc[df.fieldname], frm.doc[df.fieldname])
    );
}

// Places the red "Changed" badge just to the RIGHT of the input box,
// vertically centred on it (in the empty space beside the field).
function add_changed_badge(ctrl) {
    if (!ctrl || !ctrl.$wrapper) return;

    const $wrap = ctrl.$wrapper.find('.control-input-wrapper').first();
    const $host = $wrap.length ? $wrap : ctrl.$wrapper;
    $host.css('position', 'relative');

    let top = '50%';
    const $t = $host
        .find('.attached-file:visible, .control-input:visible, .like-disabled-input:visible')
        .first();
    if ($t.length) {
        const y = $t.offset().top - $host.offset().top + $t.outerHeight() / 2;
        top = y + 'px';
    }

    $host.append(`
        <span class="changed-badge indicator-pill red" style="
            position: absolute; left: calc(100% + 12px); top: ${top};
            transform: translateY(-50%);
            white-space: nowrap; pointer-events: none;">Changed</span>
    `);
}

function update_parent_badges(frm) {
    if (!frm._src_doc) return;
    const changed = new Set(get_changed_parent_fields(frm).map(df => df.fieldname));

    frappe.get_meta(PARENT_DT).fields.forEach(df => {
        if (!is_compared_parent_field(df)) return;
        const field = frm.fields_dict[df.fieldname];
        if (!field || !field.$wrapper) return;

        field.$wrapper.find('.changed-badge').remove();

        if (changed.has(df.fieldname)) {
            add_changed_badge(field);
        }
    });
}

// ─── Child row status ─────────────────────────────────────────────
function get_changed_child_fields(frm, row) {
    const src = row.source_row && frm._src_rows ? frm._src_rows[row.source_row] : null;
    if (!src) return [];
    return frappe.get_meta(CHILD_DT).fields.filter(df =>
        is_compared_child_field(df) &&
        values_differ(df, src[df.fieldname], row[df.fieldname])
    );
}

function compute_status(frm, row) {
    const src = row.source_row && frm._src_rows ? frm._src_rows[row.source_row] : null;

    // No matching row in the cancelled doc = newly added row
    if (!src) return STATUS.NEW;

    return get_changed_child_fields(frm, row).length ? STATUS.CHANGED : STATUS.NOT_CHANGED;
}

function update_row_status(frm, row) {
    const status = compute_status(frm, row);
    // The Row Status field only ever holds "Changed" / "Not Changed"
    const stored = status === STATUS.CHANGED ? STATUS.CHANGED : STATUS.NOT_CHANGED;
    // Direct assignment: keeps the form from being marked dirty on load
    if (row.row_status !== stored) row.row_status = stored;
    return status;
}

function refresh_all_statuses(frm) {
    (frm.doc[CHILD_TABLE] || []).forEach(row => update_row_status(frm, row));
}

// ─── Row colouring ────────────────────────────────────────────────
function badge_html(status, style) {
    return `<span class="row-status-badge" style="
        display: inline-block;
        font-size: 10px;
        font-weight: 500;
        line-height: 1.4;
        color: #fff;
        background: ${style.badge};
        border-radius: 4px;
        padding: 1px 6px;
        margin-right: 6px;
        vertical-align: middle;
        white-space: nowrap;
        pointer-events: none;">${status}</span>`;
}

// Force a background even over Frappe's own grid CSS
function set_bg($els, color) {
    $els.each(function () {
        if (color) this.style.setProperty('background-color', color, 'important');
        else this.style.removeProperty('background-color');
    });
}

function reset_row_style(grid_row) {
    const $row = grid_row && grid_row.row;
    if (!$row || !$row.length) return;

    set_bg($row, '');
    set_bg($row.children(), '');
    $row.css('box-shadow', '').removeAttr('title');
    $row.find('.row-status-badge').remove();
    $row.find('.amend-changed-cell').removeClass('amend-changed-cell').removeAttr('title');
}

function colour_row(frm, cdn, attempt = 0) {
    // Wait until the cancelled doc is loaded, otherwise every row is treated as unmatched
    if (!frm._src_rows) return;

    const row = frappe.get_doc(CHILD_DT, cdn);
    if (!row) return;

    const status = compute_status(frm, row);
    const style  = STYLE[status] || STYLE[STATUS.NOT_CHANGED];

    const grid     = frm.fields_dict[CHILD_TABLE] && frm.fields_dict[CHILD_TABLE].grid;
    const grid_row = grid && grid.grid_rows_by_docname && grid.grid_rows_by_docname[cdn];

    if (!grid_row || !grid_row.row) {
        if (attempt < 5) setTimeout(() => colour_row(frm, cdn, attempt + 1), 100);
        return;
    }

    // Table view: colours only, no wording
    reset_row_style(grid_row);

    if (status !== STATUS.NOT_CHANGED) {
        const $row = grid_row.row;
        set_bg($row, style.bg);
        set_bg($row.children(), style.bg);
        $row.css('box-shadow', `inset 3px 0 0 ${style.badge}`);

        if (status === STATUS.CHANGED) {
            const src     = frm._src_rows[row.source_row] || {};
            const changed = get_changed_child_fields(frm, row);

            // Hovering the row lists the changed fields (also covers fields
            // that are not shown as columns in the table)
            $row.attr('title', __('Changed fields: {0}', [
                changed.map(df => __(df.label || df.fieldname)).join(', ')
            ]));

            // Highlight each changed field that has a column in the table
            changed.forEach(df => {
                const $cell = $row.find(`.grid-static-col[data-fieldname="${df.fieldname}"]`);
                if (!$cell.length) return;

                set_bg($cell, CHANGED_CELL_BG);
                $cell.addClass('amend-changed-cell').attr('title', __('Was: {0}', [
                    String(src[df.fieldname] ?? '') || __('(empty)')
                ]));
            });
        }
    }

    // Row popup ("Editing Row"): "Changed" wording stays here
    update_row_form_badges(frm, grid_row, row, status);
}

function update_row_form_badges(frm, grid_row, row, status) {
    const gf = grid_row.grid_form;
    if (!gf || !gf.fields_dict) return;

    const src = row.source_row && frm._src_rows ? frm._src_rows[row.source_row] : null;

    frappe.get_meta(CHILD_DT).fields.forEach(df => {
        if (!is_compared_child_field(df)) return;
        const ctrl = gf.fields_dict[df.fieldname];
        if (!ctrl || !ctrl.$wrapper) return;

        ctrl.$wrapper.find('.changed-badge').remove();

        if (src && values_differ(df, src[df.fieldname], row[df.fieldname])) {
            add_changed_badge(ctrl);
        }
    });

    let $title = gf.wrapper.find('.grid-form-heading .panel-title').first();
    if (!$title.length) $title = gf.wrapper.find('.grid-form-heading').first();
    $title.find('.amend-title-badge').remove();

    if (status === STATUS.CHANGED) {
        const style = STYLE[status];
        $title.append(
            `<span class="amend-title-badge" style="margin-left: 8px;">${badge_html(status, style)}</span>`
        );
    }

    if (status === STATUS.NEW) {
        const style = STYLE[status];
        $title.append(
            `<span class="amend-title-badge" style="margin-left: 8px;">${badge_html(status, style)}</span>`
        );
    }
}

// Grid rows are re-rendered by Frappe (e.g. when the row form is closed),
// which wipes the badges, so re-apply them whenever the grid changes.
function observe_grid(frm) {
    const grid = frm.fields_dict[CHILD_TABLE] && frm.fields_dict[CHILD_TABLE].grid;
    if (!grid || frm._grid_observer) return;

    const target = grid.wrapper[0];
    if (!target) return;

    const opts = { childList: true, subtree: true };
    let timer;

    frm._grid_observer = new MutationObserver(() => {
        clearTimeout(timer);
        timer = setTimeout(() => {
            if (!should_compare(frm) || !frm._src_rows) return;
            frm._grid_observer.disconnect();
            highlight_all_rows(frm);
            frm._grid_observer.observe(target, opts);
        }, 150);
    });
    frm._grid_observer.observe(target, opts);
}

function highlight_all_rows(frm) {
    (frm.doc[CHILD_TABLE] || []).forEach(row => colour_row(frm, row.name));
}

// ─── Summary message at the top of the form ───────────────────────
function show_summary(frm) {
    if (!frm._src_doc) return;
    const lines = [];

    const changed = get_changed_parent_fields(frm)
        .filter(df => !SUMMARY_IGNORE.has(df.fieldname));
    if (changed.length) {
        const labels = changed.map(df =>
            frappe.utils.escape_html(__(df.label || df.fieldname))
        );
        lines.push(__('Changed fields: {0}', [labels.join(', ')]));
    }

    const rows = frm.doc[CHILD_TABLE] || [];
    const changed_rows = rows.filter(r => compute_status(frm, r) === STATUS.CHANGED).length;
    if (changed_rows) {
        lines.push(__('Dependents: {0} changed.', [changed_rows]));
    }

    const linked = new Set(rows.map(r => r.source_row).filter(Boolean));
    const removed = (frm._src_list || []).filter(r => !linked.has(r.name));
    if (removed.length) {
        lines.push(__('{0} dependent row(s) removed since {1}.',
            [removed.length, frm.doc.amended_from]));
    }

    // Own element (not frm.set_intro) so it never stacks or clashes with
    // Frappe's built-in messages such as "Submit this document to confirm".
    frm.$wrapper.find('.amend-summary').remove();
    if (lines.length) {
        const $box = $(`<div class="amend-summary alert alert-warning"
            style="margin-bottom: 12px;">${lines.join('<br>')}</div>`);
        frm.layout.wrapper.prepend($box);
    }
}

// ─── Other helpers ────────────────────────────────────────────────
function change_attach_button_text(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    let btn_text = row.relationship === 'Spouse'
        ? 'Upload Marriage Certificate'
