        $row.find('[data-fieldname="marriage_birth_certificate"] .attached-file-link').text(btn_text);
        $row.find('[data-fieldname="marriage_birth_certificate"] .attachment-btn span').text(btn_text);
        $row.find('[data-fieldname="marriage_birth_certificate"] label').text(btn_text);
