}

function setup_show_all_toggle(frm) {
    $(frm.wrapper).off('click', '.show-all-btn').on('click', '.show-all-btn', function () {
        $(this).closest('ul').find('.remove-btn').hide();
        frm.page.sidebar.find('.explore-btn').hide();
    });
}

frappe.ui.form.on('Claim Approval', {

    refresh(frm) {
        const allowed_roles_pay = ['Insurance Manager', 'Insurance User'];
        const has_role_pay = allowed_roles_pay.some(role => frappe.user_roles.includes(role));
        
        frm.set_df_property('checked_by_officer', 'read_only', 1);
        frm.set_df_property('checked_by_manager', 'read_only', 1);
        
        if (frappe.user.has_role('Insurance Manager') && frm.doc.checked_by_officer == 1) {
            frm.set_df_property('checked_by_manager', 'read_only', 0);
        } 
        
        if (frappe.user.has_role('Insurance User') && frm.doc.checked_by_manager != 1) {
            frm.set_df_property('checked_by_officer', 'read_only', 0);
        }
        
        const allowed_roles = ['Insurance Manager', 'Insurance User'];
        const has_role = frappe.user.has_role(allowed_roles);
        if(frm.doc.checked_by_officer == 1 || frm.doc.checked_by_manager == 1 || has_role){
            frm.toggle_display('payment_processing_section', true);
        } else {
             frm.toggle_display('payment_processing_section', false);
        }

        frm.set_df_property('proceed_to_payments', 'read_only', !has_role_pay);
        frm.refresh_field('proceed_to_payments');

        frm.set_df_property('opd_section', 'hidden', 1);
        frm.set_df_property('surgical_section', 'hidden', 1);
        frm.set_df_property('approved_amount', 'hidden', 1);
        frm.set_df_property('remark', 'hidden', 1);
        frm.set_df_property('rejected', 'hidden', 1);

        // Configure Grid permissions and delete prevention
        let grid = frm.fields_dict['bill_approved_amount'].grid;
        grid.cannot_add_rows = true;
        grid.cannot_delete_rows = true;
        grid.refresh();

        // Hide Delete buttons on load
        setTimeout(() => {
            $(frm.fields_dict['bill_approved_amount'].wrapper)
                .find('.grid-footer .btn-danger, .grid-delete-rows, .btn[data-action="delete_rows"]')
                .hide();
        }, 200);

        // Re-hide delete buttons when checkbox toggled
        $(frm.fields_dict['bill_approved_amount'].wrapper)
            .on('click', '.grid-row-check, input[type="checkbox"]', function () {
                setTimeout(() => {
                    $(frm.fields_dict['bill_approved_amount'].wrapper)
                        .find('.grid-footer .btn-danger, .grid-delete-rows, .btn[data-action="delete_rows"]')
                        .hide();
                }, 100);
            });

        const observer = new MutationObserver(() => {
            grid.wrapper.find('.btn-danger').hide();
            $('.grid-row-open .btn-danger').hide();
        });
        observer.observe(grid.wrapper[0], { childList: true, subtree: true });

        // Filters - only show Active claim groups not already used
        frappe.call({
            method: 'get_used_claim_groups',
            callback: function (r) {
                let used = (r.message && r.message.length) ? r.message : ['__none__'];

                frm.set_query('claim_group', function () {
                    return {
                        filters: {
                            group_status: 'Active',
                            name: ['not in', used]
                        }
                    };
                });
            }
        });

        // Initialize claim_group logic on load
        if (frm.doc.claim_group) {
            if (frm.doc.docstatus === 0) frm.trigger('claim_group');
            frm.set_df_property('payment_processing_section', 'hidden', 0);
        } else {
            frm.set_df_property('payment_processing_section', 'hidden', 1);
        }

        // Apply pill setup immediately
        setup_claim_nos_pills(frm);

        if (frm.doc.view_category_balences || frm.doc.docstatus === 0) {
            frm.set_df_property('amount_for_catagory', 'hidden', 0);
        } else {
            frm.set_df_property('amount_for_catagory', 'hidden', 1);
        }

        if (frm.doc.docstatus === 1) {
            if (frm.doc.checked_by_manager == 1 && frm.doc.checked_by_officer == 1) {
                frm.set_df_property('checked_by_manager', 'hidden', 0);
                frm.set_df_property('checked_by_officer', 'hidden', 0);
            } else {
                frm.set_df_property('checked_by_manager', 'hidden', 1);
                frm.set_df_property('checked_by_officer', 'hidden', 1);
            }
            
            frm.set_df_property('previous_approved', 'hidden', 1);
            frm.set_df_property('balance_n', 'hidden', 1);
            frm.set_df_property('view_category_balences', 'hidden', 1);
            frm.set_df_property('approved_amount', 'hidden', 0);
            frm.set_df_property('remark', 'hidden', 0);
            frm.set_df_property('rejected', 'hidden', 0);
        }

        if (frm.doc.docstatus != 0) {
            if (frm.doc.claim_no) {
                frm.set_df_property('surgical_section', 'hidden', 0);
            } else {
                frm.set_df_property('opd_section', 'hidden', 0);
            }
        }
    },

    // NOTE: this handler only ever runs for the "surgical" (single claim)
    // form type. For "monthly summary" (OPD) claims the field is kept
    // read-only in get_claims_for_group(), so the user can never type into
    // it directly - its value only ever changes via the bill_approved_amount
    // child table handler below.
    approved_amount(frm) {
        const field = frm.get_field('approved_amount');
        const is_editable = field && !field.df.read_only && !field.df.hidden && frm.doc.docstatus === 0;
        if (!is_editable) return;

        if (!frm.doc.claim_group) return;   // only skip when there's nothing to compute against

        if (frm.doc.approved_amount < 0) {
            frappe.msgprint(__('Value cannot be negative'));
            frm.set_value('approved_amount', 0);
            return;
        }

        // Approved amount can never exceed:
        //  - the remaining category balance (limit_n - previous_approved), and
        //  - the amount actually requested for this claim (requested_amount).
        // balance_n is simply the derived result of these two caps, so
        // clamping to their minimum keeps balance_n from ever going negative.
        // Rounded to currency precision (2dp) throughout - unrounded float
        // subtraction/addition here is what produces values like
        // 24206.620000000003, which Frappe then rejects as a post-submit
        // change even though it's really the same number.
        const available_balance = flt(frm.doc.limit_n - frm.doc.previous_approved, 2);
        const requested = flt(frm.doc.requested_amount, 2);
        const max_allowed = flt(Math.max(Math.min(available_balance, requested), 0), 2);

        if (frm.doc.approved_amount > max_allowed) {
            frappe.msgprint(__('Value cannot be greater than the available balance or the requested amount.'));
            frm.set_value('approved_amount', max_allowed);
            return;
        }

        frm.set_value('balance_n', flt(frm.doc.limit_n - frm.doc.approved_amount - frm.doc.previous_approved, 2));
    },

    claim_group(frm) {
        if (frm.doc.claim_group) {
            frm.set_df_property('approved_amount', 'hidden', 0);
            frm.set_df_property('remark', 'hidden', 0);
            frm.set_df_property('rejected', 'hidden', 0);

            get_claims_for_group(frm);
            build_cover_balance_table(frm);

            if (!frm.doc.__islocal && (frm.doc.claim_nos || []).length) {
                setup_claim_nos_pills(frm);
            } else {
                frappe.db.get_doc('Employee Claim Group', frm.doc.claim_group).then(source_doc => {
                    let grid_field = frm.get_field('claim_nos');
                    frm.clear_table('claim_nos');

                    const child_doctype = grid_field.df.options;

                    (source_doc.claims || []).forEach(row => {
                        let child = frappe.model.add_child(frm.doc, child_doctype, 'claim_nos');
                        child.claim = row.claim;
                    });

                    frm.refresh_field('claim_nos');
                    setup_claim_nos_pills(frm);
                });
            }

            const allowed_roles = ['Insurance Manager', 'Insurance User'];
            const has_role = allowed_roles.some(role => frappe.user_roles.includes(role));
            frm.set_df_property('proceed_to_payments', 'read_only', !has_role);

            if (frm.doc.docstatus === 1) {
                frm.set_df_property('payment_processing_section', 'hidden', 0);
            } else {
                frm.set_df_property('payment_processing_section', 'hidden', !has_role);
            }
            frm.refresh_field('payment_processing_section');
        } else {
            clear_bottom_form(frm);
            frm.set_df_property('approved_amount', 'hidden', 1);
            frm.set_df_property('remark', 'hidden', 1);
            frm.set_df_property('rejected', 'hidden', 1);
            frm.set_df_property('opd_section', 'hidden', 1);
            frm.set_df_property('surgical_section', 'hidden', 1);
            frm.set_df_property('payment_processing_section', 'hidden', 1);
        }
    },

    rejected(frm) {
        if (!frm.doc.claim_group) return;

        if (frm.doc.rejected) {
            frm.set_value('approved_amount', 0);
            frm.set_df_property('approved_amount', 'hidden', 1);

            if (!frm.doc.claim_no) {
                (frm.doc.bill_approved_amount || []).forEach(row => {
                    row.approved_amount = flt('');
                });
                frm.refresh_field('bill_approved_amount');
                frm.set_df_property('opd_section', 'hidden', 1);
            } else {
                frm.set_df_property('surgical_section', 'hidden', 1);
            }
        } else {
            frm.set_df_property('approved_amount', 'hidden', 0);
            if (!frm.doc.claim_no) {
                frm.set_df_property('opd_section', 'hidden', 0);
            } else {
                frm.set_df_property('surgical_section', 'hidden', 0);
            }
        }

        build_cover_balance_table(frm);
    },

    view_category_balences(frm) {
        if (frm.doc.view_category_balences) {
            frm.set_df_property('amount_for_catagory', 'hidden', 0);
        } else {
            frm.set_df_property('amount_for_catagory', 'hidden', 1);
        }
    }
});

