frappe.ui.form.on('Approved Bill Amounts', {
    approved_amount: function (frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        let req = flt(row.requested_amount, 2);
        let apv = flt(row.approved_amount, 2);

        // 1. No negative values
        if (apv < 0) {
            frappe.msgprint({
                message: __('Approved Amount cannot be negative.'),
                indicator: 'red'
            });
            frappe.model.set_value(cdt, cdn, 'approved_amount', 0);
            return;
        }

        // 2. Cannot exceed requested_amount
        if (apv > req) {
            frappe.msgprint({
                message: __('Approved Amount cannot exceed Requested Amount.', [
                    frappe.format(apv, { fieldtype: 'Currency' }),
                    frappe.format(req, { fieldtype: 'Currency' })
                ])
            });
            frappe.model.set_value(cdt, cdn, 'approved_amount', req);
            return;
        }

        // 3. Cannot exceed remaining category balance (per amount_for_catagory)
        const cache = frm.__cover_balance_data;
        if (cache && row.category) {
            const limit_val = cache.limit_val || {};
            const approved_val = cache.approved_val || {};

            if (limit_val.hasOwnProperty(row.category)) {
                const limit = flt(limit_val[row.category], 2);
                const prev_approved = flt(approved_val[row.category], 2);

                let other_rows_total = 0;
                (frm.doc.bill_approved_amount || []).forEach(r => {
                    if (r.name !== row.name && r.category === row.category) {
                        other_rows_total += flt(r.approved_amount, 2);
                    }
                });

                const max_allowed = flt(Math.max(limit - prev_approved - other_rows_total, 0), 2);

                if (apv > max_allowed) {
                    frappe.msgprint({
                        message: __('Approved Amount for category "{0}" exceeds the available balance. Maximum allowed here is {1}.', [
                            row.category,
                            format_currency(max_allowed)
                        ]),
                        indicator: 'red'
                    });
                    frappe.model.set_value(cdt, cdn, 'approved_amount', max_allowed);
                    return;
                }
            }
        }

        // Calculation logic when validation passes.
        // req/apv are already guaranteed >= 0 and apv <= req above, so
        // differnce (req - apv) can never go negative. balance is floored
        // at 0 defensively for the same reason. Every result below is
        // rounded to currency precision (2dp) before being written back -
        // unrounded float math is what produces values like
        // 24206.620000000003, which Frappe rejects as a post-submit change.
        let bal = row.balance || 0;
        let new_balance = flt(bal - apv, 2);
        if (new_balance < 0) new_balance = 0;

        frappe.model.set_value(cdt, cdn, 'differnce', flt(req - apv, 2));
        frm.refresh_field('differnce');
        frappe.model.set_value(cdt, cdn, 'balance', new_balance);
        frm.refresh_field('differnce');

        // approved_amount on the parent (Claim Approval) is a pure rollup
        // for monthly-summary/OPD claims - it is kept read-only in
        // get_claims_for_group() and only ever updated here, from the sum
        // of this child table's approved_amount column. Each row is already
        // floored at 0 above, so the total can never go negative either.
        let total = 0;
        (frm.doc.bill_approved_amount || []).forEach(r => {
            total += flt(r.approved_amount, 2);
        });
        total = flt(total, 2);
        if (total < 0) total = 0;

        frm.set_value('approved_amount', total);
        frm.refresh_field('approved_amount');

        if (frm.doc.approved_amount < total) {
            frappe.msgprint({
                message: __('Amount total mismatch.'),
                indicator: 'red'
            });
        }

        build_cover_balance_table(frm);
    }
});

