function apply_cert_links(frm) {
    let grid_wrapper = frm.fields_dict['dependents'].grid.wrapper;

    grid_wrapper.find('.grid-row').each(function () {
        let row_name = $(this).attr('data-name');
        if (!row_name) return;

        // Get child doctype name
        let child_doctype = frm.fields_dict['dependents'].grid.doctype;
        let row = locals[child_doctype][row_name];
        if (!row || !row.cert) return;

        let cell = $(this).find('[data-fieldname="cert"]');
        if (!cell.length) return;

        // Skip if link already injected
        if (cell.find('a').length) return;

        // cert field value is the full URL
        let url = row.cert;
        
        let cert = row.relationship != "Spouse" ? "Birth Certificate" : "Marriage Certificate";

        cell.find('.static-area, .like-disabled-input').html(
            `<a href="${url}" 
                target="_blank"
                onclick="event.stopPropagation()"
                style="font-weight:bold;">
                ${cert}
            </a>`
        );
    });
}

