frappe.ui.form.on('Claim Summary', {
    refresh(frm) {
        setup_summary_approvals(frm);
    },

    group_report(frm) {
        open_report(frm, 'Monthly Group Report - Insurance', (report_obj) => open_print_window_all(report_obj, true));
    },

    summary_report(frm) {
        open_report(frm, 'Monthly Group Report - Insurance Summary', (report_obj) => print_summary_report(report_obj, true));
    },

    approved_summary_report(frm) {
        open_report(frm, 'Monthly Group Report - Insurance Approved Summary', (report_obj) => print_summary_report(report_obj, true));
    },
});

function open_report(frm, report_name, on_ready) {
    frappe.route_options = { group_month: frm.doc.name };
    frappe.set_route('query-report', report_name);

    var interval = setInterval(function () {
        var report_entry = frappe.query_reports && frappe.query_reports[report_name];
        var report_obj = report_entry && report_entry._report_obj;

        if (report_obj && frappe.query_report && frappe.query_report.data) {
            clearInterval(interval);
            on_ready(report_obj);
        }
    }, 500);

    setTimeout(function () {
        clearInterval(interval);
    }, 15000);
}

async function setup_summary_approvals(frm) {
    frm.layout.wrapper.find('.ca-approvals-wrap').remove();

    if (frm.is_new() || !/^\d{4}-\d{2}$/.test(frm.doc.name)) return;

    const token = (frm.__appr_token = (frm.__appr_token || 0) + 1);
    
    const start_m = moment(frm.doc.name + '-01', 'YYYY-MM-DD').add(1, 'months').startOf('month');
    const period_start = start_m.format('YYYY-MM-DD');
    const period_end = start_m.clone().endOf('month').format('YYYY-MM-DD');

    // const period_start = frappe.datetime.add_months(frm.doc.name + '-01', 1);
    // const period_end = frappe.datetime.month_end(period_start);
    const from_ts = period_start + ' 00:00:00';
    const to_ts = period_end + ' 23:59:59.999999';

    const filters = {
        // summary: frm.doc.name,
        claim_status: 'Approved',
        docstatus: 1,
        modified: ['between', [from_ts, to_ts]]
    };

    let names;
    try {
        const rows = await frappe.xcall('frappe.client.get_list', {
            doctype: 'Claim Approval',
            filters: filters,
            fields: ['name'],
            limit_page_length: 0
        });
        names = rows.map(d => d.name);
    } catch (e) {
        console.error('Claim Summary approvals failed', e);
        return;
    }

    if (token !== frm.__appr_token) return;

    frm.layout.wrapper.find('.ca-approvals-wrap').remove();

    const $wrap = $(`
        <div class="ca-approvals-wrap form-documents" style="margin-top:15px">
            <div class="document-link" style="margin:0">
                <div class="document-link-badge"
                     style="cursor:pointer;display:inline-flex;align-items:center;
                            background-color:var(--control-bg);border-radius:var(--border-radius);
                            padding:5px 10px;line-height:1;">
                    <span class="count"
                          style="display:inline-block;background-color:var(--gray-500);color:#fff;
                                 font-size:var(--text-xs);font-weight:600;line-height:1;
                                 padding:3px 6px;border-radius:4px;margin-right:8px;">${names.length}</span>
                    <a class="badge-link"
                       style="color:var(--text-color);font-size:var(--text-sm);font-weight:400;
                              text-decoration:none;">${__('Claim Approvals')}</a>
                </div>
            </div>
        </div>`);

    const field = frm.fields_dict.total_claim_amount;
    if (field && field.wrapper) {
        $(field.wrapper).after($wrap);
    } else {
        frm.layout.wrapper.append($wrap);
    }

    $wrap.find('.document-link-badge').hover(
        function () { $(this).find('.badge-link').css('text-decoration', 'underline'); },
        function () { $(this).find('.badge-link').css('text-decoration', 'none'); }
    );

    $wrap.find('.document-link-badge').on('click', () => {
        frappe.route_options = {
            // summary: frm.doc.name,
            claim_status: 'Approved',
            docstatus: 1,
            modified: ['between', [from_ts, to_ts]]
        };
        frappe.set_route('List', 'Claim Approval');
    });
}

