frappe.ui.form.on('Employee Claim Group', {
	refresh(frm) {
        const field = frm.fields_dict['claims'];

        if (field && field.$wrapper) {
            const wrapperEl = field.$wrapper[0];

            // Hide remove (x) buttons — prevents removing via UI
            field.$wrapper.find('.btn-remove').hide();

            // Hide/disable the search input — prevents adding new ones
            field.$wrapper.find('.awesomplete input, input.input-with-feedback')
                .prop('disabled', true)
                .hide();

            // Inject style for the "clicked" state only (default stays untouched on load)
            if (!document.getElementById('interviewer-pill-style')) {
                const style = document.createElement('style');
                style.id = 'interviewer-pill-style';
                // style.innerHTML = `
                //     [data-fieldname="interviewers"] .data-pill.pill-clicked {
                //         background-color: #e3f2fd !important;
                //         color: #1565c0 !important;
                //         border: 1px solid #90caf9 !important;
                //     }
                // `;
                document.head.appendChild(style);
            }

            // Remove old listener if it exists (avoid duplicates on refresh)
            if (wrapperEl._pill_click_handler) {
                wrapperEl.removeEventListener('click', wrapperEl._pill_click_handler, true);
            }

            const handler = function (e) {
                const label = e.target.closest('.btn-link-to-form');
                if (label && wrapperEl.contains(label)) {
                    e.preventDefault();
                    e.stopPropagation();
                    e.stopImmediatePropagation();

                    const $pill = $(label).closest('.data-pill');
                    const docId = decodeURIComponent($pill.attr('data-value') || label.textContent.trim());

                    console.log('Clicked doc ID:', docId);

                    // Toggle color on this pill only
                    $pill.toggleClass('pill-clicked');
                }
            };

            wrapperEl.addEventListener('click', handler, true); // capture phase
            wrapperEl._pill_click_handler = handler;
        }
    }
});
